import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.C-si7TFR.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/how_to_get_weixin_work_credential.md","filePath":"zh/how_to_get_weixin_work_credential.md"}'),p={name:"zh/how_to_get_weixin_work_credential.md"};function c(n,e,i,l,k,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="企业微信应用凭据" tabindex="-1">企业微信应用凭据 <a class="header-anchor" href="#企业微信应用凭据" aria-label="Permalink to &quot;企业微信应用凭据&quot;">​</a></h2><p>该凭据需要以下5个信息，这些信息需要登陆企业微信后台后才可以获得。</p><blockquote><p>原截图含凭据、令牌或应用标识，已停止公开。请在对应平台自行创建秘密并填入本地配置。</p></blockquote><h2 id="corpid-企业id" tabindex="-1">CorpID（企业ID） <a class="header-anchor" href="#corpid-企业id" aria-label="Permalink to &quot;CorpID（企业ID）&quot;">​</a></h2><p>位置：【我的企业】=》【企业信息】</p><p>链接：<a href="https://work.weixin.qq.com/wework_admin/frame#profile" target="_blank" rel="noreferrer">https://work.weixin.qq.com/wework_admin/frame#profile</a></p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h2 id="corpsecret" tabindex="-1">CorpSecret <a class="header-anchor" href="#corpsecret" aria-label="Permalink to &quot;CorpSecret&quot;">​</a></h2><p>位置：【应用管理】=&gt;【应用】=&gt;【自建】</p><p>链接：<a href="https://work.weixin.qq.com/wework_admin/frame#apps" target="_blank" rel="noreferrer">https://work.weixin.qq.com/wework_admin/frame#apps</a></p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="自建应用" tabindex="-1">自建应用 <a class="header-anchor" href="#自建应用" aria-label="Permalink to &quot;自建应用&quot;">​</a></h3><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="获取corpsecret" tabindex="-1">获取CorpSecret <a class="header-anchor" href="#获取corpsecret" aria-label="Permalink to &quot;获取CorpSecret&quot;">​</a></h3><p>点击Secret右边的【查看】按钮，可以在企业微信客户端应用上接收到我们需要的CorpSecret信息。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>打开客户端软件，如下可以看到一条消息，点击【前往查看】按钮即可以看到CorpSecret。</p><blockquote><p>原截图含凭据、令牌或应用标识，已停止公开。请在对应平台自行创建秘密并填入本地配置。</p></blockquote><h2 id="agentid" tabindex="-1">AgentId <a class="header-anchor" href="#agentid" aria-label="Permalink to &quot;AgentId&quot;">​</a></h2><p>位置：【应用管理】=&gt;【应用】=&gt;【自建】</p><p>链接：<a href="https://work.weixin.qq.com/wework_admin/frame#apps" target="_blank" rel="noreferrer">https://work.weixin.qq.com/wework_admin/frame#apps</a></p><p>如上，打开自建应用后，就可以看到AgentId。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h2 id="token和encodingaeskey" tabindex="-1">Token和EncodingAESKey <a class="header-anchor" href="#token和encodingaeskey" aria-label="Permalink to &quot;Token和EncodingAESKey&quot;">​</a></h2><p>位置：打开自建应用，进入功能选项下的【接受消息】，点击【设置API接收】按钮。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>其中Token和EncodingAESKey是可以在企微平台上自动生成的。其中接收的消息类型选择如下，注意要勾选微信客服消息和事件。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><h3 id="测试回调接口" tabindex="-1">测试回调接口 <a class="header-anchor" href="#测试回调接口" aria-label="Permalink to &quot;测试回调接口&quot;">​</a></h3><p>前面我们创建保存凭据后，默认是未启用的。进入【应用开发】&gt;【凭据管理】，把前面创建的企微应用凭据启用。</p><blockquote><p>原截图含凭据、令牌或应用标识，已停止公开。请在对应平台自行创建秘密并填入本地配置。</p></blockquote><p>回调企业微信的自建应用的【接受消息服务器配置】，我们把前面生成的回调接口地址（<code>http://xxx.com/v1/weixin_work/callback/[corpId]/[agentId]</code>）输入进去。</p><p>点击保存后，如果接口一切正常，会提示保存成功，说明企微推送给BotMan系统的回调接口的数据解密成功，整个流程跑通了。</p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote><p>如果想了解企微跟开发者服务器的交互过程，可以参考企微的官方文档：<a href="https://developer.work.weixin.qq.com/document/path/90930" target="_blank" rel="noreferrer">回调配置</a></p><blockquote><p>历史界面图片在复核并重拍前不展示，请按当前界面核对操作。</p></blockquote>',37)])])}const _=o(p,[["render",c]]);export{q as __pageData,_ as default};
